import { test, expect } from '@playwright/test';

test.describe('Save Search Query', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    await page.waitForLoadState('networkidle');
  });

  test('should save a search query with a custom name', async ({ page }) => {
    // Perform a search
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('playwright testing');
    await page.getByRole('button', { name: /search/i }).click();

    // Wait for results to load
    await page.waitForLoadState('networkidle');

    // Open save search dialog
    const saveButton = page.getByRole('button', { name: /save search/i });
    await saveButton.click();

    // Fill in the save search form
    const nameInput = page.getByLabel(/search name/i);
    await nameInput.fill('My Playwright Tests');

    // Submit the save form
    const confirmButton = page.getByRole('button', { name: /confirm|save/i });
    await confirmButton.click();

    // Verify success message
    const successMessage = page.getByText(/search saved successfully/i);
    await expect(successMessage).toBeVisible();
  });

  test('should display saved searches in the sidebar', async ({ page }) => {
    // Perform and save a search
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('automation testing');
    await page.getByRole('button', { name: /search/i }).click();

    await page.waitForLoadState('networkidle');

    const saveButton = page.getByRole('button', { name: /save search/i });
    await saveButton.click();

    const nameInput = page.getByLabel(/search name/i);
    await nameInput.fill('Automation Tests');

    const confirmButton = page.getByRole('button', { name: /confirm|save/i });
    await confirmButton.click();

    await expect(page.getByText(/search saved successfully/i)).toBeVisible();

    // Navigate to saved searches section
    const savedSearchesTab = page.getByRole('tab', { name: /saved searches/i });
    await savedSearchesTab.click();

    // Verify the saved search appears in the list
    const savedSearchItem = page.getByText('Automation Tests');
    await expect(savedSearchItem).toBeVisible();
  });

  test('should load a saved search when clicked', async ({ page }) => {
    // First, save a search
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('typescript');
    await page.getByRole('button', { name: /search/i }).click();

    await page.waitForLoadState('networkidle');

    const saveButton = page.getByRole('button', { name: /save search/i });
    await saveButton.click();

    const nameInput = page.getByLabel(/search name/i);
    await nameInput.fill('TypeScript Search');

    const confirmButton = page.getByRole('button', { name: /confirm|save/i });
    await confirmButton.click();

    await expect(page.getByText(/search saved successfully/i)).toBeVisible();

    // Clear the current search
    await searchInput.clear();

    // Navigate to saved searches
    const savedSearchesTab = page.getByRole('tab', { name: /saved searches/i });
    await savedSearchesTab.click();

    // Click on the saved search
    const savedSearchLink = page.getByRole('button', { name: /TypeScript Search/i });
    await savedSearchLink.click();

    // Verify the search is loaded
    await expect(searchInput).toHaveValue('typescript');
    await page.waitForLoadState('networkidle');
  });

  test('should prevent saving search with empty name', async ({ page }) => {
    // Perform a search
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('test query');
    await page.getByRole('button', { name: /search/i }).click();

    await page.waitForLoadState('networkidle');

    // Open save search dialog
    const saveButton = page.getByRole('button', { name: /save search/i });
    await saveButton.click();

    // Try to submit without filling the name
    const confirmButton = page.getByRole('button', { name: /confirm|save/i });
    await confirmButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/name is required|please enter a name/i);
    await expect(errorMessage).toBeVisible();

    // Verify the dialog is still open
    const nameInput = page.getByLabel(/search name/i);
    await expect(nameInput).toBeVisible();
  });

  test('should delete a saved search', async ({ page }) => {
    // Save a search first
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('delete test');
    await page.getByRole('button', { name: /search/i }).click();

    await page.waitForLoadState('networkidle');

    const saveButton = page.getByRole('button', { name: /save search/i });
    await saveButton.click();

    const nameInput = page.getByLabel(/search name/i);
    await nameInput.fill('Temporary Search');

    const confirmButton = page.getByRole('button', { name: /confirm|save/i });
    await confirmButton.click();

    await expect(page.getByText(/search saved successfully/i)).toBeVisible();

    // Navigate to saved searches
    const savedSearchesTab = page.getByRole('tab', { name: /saved searches/i });
    await savedSearchesTab.click();

    // Find and delete the saved search
    const savedSearchItem = page.getByText('Temporary Search');
    await expect(savedSearchItem).toBeVisible();

    const deleteButton = page.getByRole('button', { name: /delete.*Temporary Search|remove.*Temporary Search/i });
    await deleteButton.click();

    // Confirm deletion if prompted
    const confirmDeleteButton = page.getByRole('button', { name: /confirm|yes|delete/i }).last();
    await confirmDeleteButton.click();

    // Verify the search is removed
    await expect(savedSearchItem).not.toBeVisible();
  });
});
